#!/bin/sh
# Renders the app icon, splash images and favicon from icon.svg / icon-foreground.svg.
# Needs rsvg-convert and ImageMagick (brew install librsvg imagemagick). Run from the repo root.
set -e
R=android/app/src/main/res
TMP=$(mktemp -d)

# Adaptive icon foreground (also the monochrome layer): same path data as the SVG.
D=$(sed -n 's/.* d="\([^"]*\)".*/\1/p' resources/icon-foreground.svg)
cat > $R/drawable-v24/ic_launcher_foreground.xml <<XML
<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by resources/render-icons.sh from resources/icon-foreground.svg. -->
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="108dp"
    android:height="108dp"
    android:viewportWidth="108"
    android:viewportHeight="108">
    <path
        android:fillColor="#FFFFFF"
        android:fillType="evenOdd"
        android:pathData="$D" />
</vector>
XML

# Legacy launcher icons (API 24-25): the adaptive art's inner two thirds.
rsvg-convert -w 1296 resources/icon.svg -o $TMP/big.png
magick $TMP/big.png -crop 864x864+216+216 +repage $TMP/inner.png
for pair in mdpi:48 hdpi:72 xhdpi:96 xxhdpi:144 xxxhdpi:192; do
  dpi=${pair%%:*}; px=${pair##*:}; r=$((px * 18 / 100)); h=$((px / 2))
  magick $TMP/inner.png -resize ${px}x${px} \( -size ${px}x${px} xc:black -fill white -draw "roundrectangle 0,0 $((px - 1)),$((px - 1)) $r,$r" \) -alpha off -compose CopyOpacity -composite $R/mipmap-$dpi/ic_launcher.png
  magick $TMP/inner.png -resize ${px}x${px} \( -size ${px}x${px} xc:black -fill white -draw "circle $h,$h $h,0" \) -alpha off -compose CopyOpacity -composite $R/mipmap-$dpi/ic_launcher_round.png
done

# Splash images: the mark centred on the brand blue, at each existing size.
for f in $R/drawable*/splash.png; do
  w=$(magick identify -format %w "$f"); h=$(magick identify -format %h "$f")
  m=$(( (w < h ? w : h) * 75 / 100 ))
  rsvg-convert -w $m -h $m resources/icon-foreground.svg -o $TMP/fg.png
  magick -size ${w}x${h} xc:'#1C2430' $TMP/fg.png -gravity center -composite "$f"
done

# Favicon for the web build.
magick $TMP/inner.png \( -size 864x864 xc:black -fill white -draw "roundrectangle 0,0 863,863 156,156" \) -alpha off -compose CopyOpacity -composite -define icon:auto-resize=48,32,16 public/favicon.ico

rm -r "$TMP"
